function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function redirect_to(string $p):never{header('Location:'.$p);exit;} function is_post():bool{return ($_SERVER['REQUEST_METHOD']??'GET')==='POST';}
