function upload_image(string $field,string $folder):?string{global $config;if(empty($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null;if($_FILES[$field]['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Image upload failed.');$max=(int)($config['app']['upload_max_bytes']??5242880);if((int)$_FILES[$field]['size']>$max)throw new RuntimeException('Image must be 5MB or smaller.');$tmp=$_FILES[$field]['tmp_name'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime])||@getimagesize($tmp)===false)throw new RuntimeException('Only valid JPG, PNG or WEBP images are allowed.');$name=bin2hex(random_bytes(18)).'.'.$allowed[$mime];$relative='assets/uploads/'.$folder.'/'.$name;$target=dirname(__DIR__).'/'.$relative;if(!is_dir(dirname($target)))mkdir(dirname($target),0755,true);if(!move_uploaded_file($tmp,$target))throw new RuntimeException('Could not save the image.');return $relative;}
